//! Pruning tables: the cocsep (corner) table and the big H48 table.
//!
//! A pruning table maps a coordinate of the cube to a lower bound on its
//! distance to solved. IDA* (see `solver`) prunes a node when its bound
//! exceeds the moves left. Two tables are used:
//!
//! * `Cocsep`: the exact distance of each cocsep coordinate (corners only),
//!   plus its symmetry class, built at startup in a fraction of a second.
//! * `H48Table`: the distance of the full H48 coordinate (corner class,
//!   msplit, eo, eslot; see `coord`), 2 bits per entry, generated by `gen`
//!   and loaded from a file (58 GiB for h11).

pub mod file;
pub mod shm;
pub use file::TableError;

use crate::coord::{cocsep, h11_key, reduce_key, N_CLASSES, N_COCSEP, N_MSPLIT, N_SLOTS};
use crate::cubie::Move;
use crate::simd::Cube;
use std::sync::atomic::{AtomicU64, Ordering};

// ---------------------------------------------------------------------------
// cocsep data
// ---------------------------------------------------------------------------

/// The cocsep table: per cocsep coordinate, its symmetry class, the
/// symmetry that maps it to the class representative ("sym to rep") and its
/// depth (distance to solved).
pub struct Cocsep {
    /// `entries[cocsep] = class << 16 | sym_to_rep << 8 | depth` (see
    /// `entry_*`).
    pub entries: Box<[u32]>,
    /// Representative cube (corners only meaningful) per class.
    pub representatives: Box<[Cube]>,
    /// Bitmask of the symmetries fixing the representative's cocsep, per
    /// class.
    pub self_symmetries: Box<[u64]>,
    /// Depth distribution of the 153090 cocsep coordinates.
    pub distribution: Box<[u64]>,
    /// Hot-path copy of `entries` packed into 3 bytes per entry (25% less
    /// L2 footprint): `class << 10 | sym_to_rep << 4 | depth` (+1 pad byte),
    /// on a transparent huge page (one TLB entry instead of ~113). (+2.8% at
    /// 48T when added, with the direct index, packed-cocsep.)
    packed: Memory,
}

/// Bytes of memory for the packed entries (3 per coordinate, and the 4-byte
/// load of the last one).
const PACKED_LEN: usize = 2 << 20;
const _: () = assert!(3 * N_COCSEP < PACKED_LEN);

/// Class of a packed cocsep entry (`Cocsep::packed`).
#[must_use]
#[inline(always)]
pub fn packed_class(packed: u32) -> usize {
    ((packed >> 10) & 0xFFF) as usize
}
/// Symmetry to the class representative of a packed cocsep entry.
#[must_use]
#[inline(always)]
pub fn packed_sym_to_rep(packed: u32) -> usize {
    ((packed >> 4) & 0x3F) as usize
}
/// Depth of a packed cocsep entry.
#[must_use]
#[inline(always)]
pub fn packed_depth(packed: u32) -> u8 {
    (packed & 15) as u8
}

/// Class of a cocsep entry (`Cocsep::entries`).
#[must_use]
#[inline(always)]
pub fn entry_class(entry: u32) -> usize {
    (entry >> 16) as usize
}
/// Symmetry to the class representative of a cocsep entry.
#[must_use]
#[inline(always)]
pub fn entry_sym_to_rep(entry: u32) -> usize {
    ((entry >> 8) & 0xFF) as usize
}
/// Depth of a cocsep entry.
#[must_use]
#[inline(always)]
pub fn entry_depth(entry: u32) -> u8 {
    (entry & 0xFF) as u8
}

impl Cocsep {
    /// Build the table: a breadth-first search (BFS) over the cocsep
    /// coordinate, then the symmetry classes.
    ///
    /// # Errors
    /// If the BFS does not find the expected number of coordinates or
    /// classes, or depths above 15 (a bug in the cube model), or the 2 MiB
    /// of packed entries cannot be allocated.
    pub fn generate() -> Result<Cocsep, TableError> {
        // BFS over the cocsep coordinate, keeping a cube for each.
        let mut depth = vec![0xFFu8; N_COCSEP];
        let mut cube_of = vec![Cube::solved(); N_COCSEP];
        let mut order = Vec::with_capacity(N_COCSEP);
        let solved = cocsep(Cube::solved());
        depth[solved] = 0;
        order.push(solved);
        let mut head = 0;
        while head < order.len() {
            let i = order[head];
            head += 1;
            for mv in Move::ALL {
                let next = cube_of[i].apply_move(mv);
                let j = cocsep(next);
                if depth[j] == 0xFF {
                    depth[j] = depth[i] + 1;
                    cube_of[j] = next;
                    order.push(j);
                }
            }
        }
        let model_error = |what, found, expected| TableError::CocsepModel {
            what,
            found,
            expected,
        };
        if order.len() != N_COCSEP {
            return Err(model_error("coordinates", order.len(), N_COCSEP));
        }
        // (Depths are below 16: they fit the packed entries' 4 bits.)
        let mut distribution = vec![0u64; 16].into_boxed_slice();
        for &d in &depth {
            let count = distribution.get_mut(usize::from(d)).ok_or(model_error(
                "a depth of",
                usize::from(d),
                15,
            ))?;
            *count += 1;
        }
        // Classes, in BFS order: the first coordinate of a class is its
        // representative; its 48 conjugates are the class's members.
        let mut class = vec![u32::MAX; N_COCSEP];
        let mut sym_to_rep = vec![0u8; N_COCSEP];
        // (Filled by class index: `into_boxed_slice` of a pushed Vec keeps a
        // shrink path, +654 bytes of solve::main.)
        let mut representatives = vec![Cube::solved(); N_CLASSES].into_boxed_slice();
        let mut self_symmetries = vec![0u64; N_CLASSES].into_boxed_slice();
        let mut n_classes = 0;
        for &i in &order {
            if class[i] != u32::MAX {
                continue;
            }
            // (Below `N_CLASSES`, so it fits in the entries and indexes the
            // class arrays.)
            let new_class = u32::try_from(n_classes)
                .ok()
                .filter(|_| n_classes < N_CLASSES)
                .ok_or(model_error("more classes than", n_classes + 1, N_CLASSES))?;
            let rep = cube_of[i];
            let mut fixing = 0u64;
            for (sym, &inverse) in crate::simd::SYM_INVERSES.iter().enumerate() {
                let j = cocsep(rep.transform(sym));
                if class[j] == u32::MAX {
                    class[j] = new_class;
                    sym_to_rep[j] = inverse;
                }
                if j == i {
                    fixing |= 1 << sym;
                }
            }
            debug_assert_eq!(sym_to_rep[i], 0);
            representatives[n_classes] = rep;
            self_symmetries[n_classes] = fixing;
            n_classes += 1;
        }
        if n_classes != N_CLASSES {
            return Err(model_error("classes", n_classes, N_CLASSES));
        }
        let entries: Box<[u32]> = (0..N_COCSEP)
            .map(|i| (class[i] << 16) | (u32::from(sym_to_rep[i]) << 8) | u32::from(depth[i]))
            .collect();
        // 2 MiB: the kernel aligns it so that it gets one huge page.
        let packed = Memory::anonymous(PACKED_LEN)?;
        // SAFETY: `3 * N_COCSEP + 1` bytes of the fresh 2 MiB (`PACKED_LEN`),
        // ours alone.
        let bytes = unsafe { std::slice::from_raw_parts_mut(packed.ptr(), 3 * N_COCSEP + 1) };
        let packed_entries = class.iter().zip(&sym_to_rep).zip(&depth);
        for (slot, ((&class, &sym_to_rep), &depth)) in
            bytes.as_chunks_mut::<3>().0.iter_mut().zip(packed_entries)
        {
            let entry = (class << 10) | (u32::from(sym_to_rep) << 4) | u32::from(depth);
            let [first, second, third, _] = entry.to_le_bytes();
            *slot = [first, second, third];
        }
        Ok(Cocsep {
            entries,
            representatives,
            self_symmetries,
            distribution,
            packed,
        })
    }

    /// A cheap stand-in for unit tests: corner depths from a BFS cut after
    /// `depth` moves (deeper coordinates get `depth + 1`, still a lower bound
    /// and still a function of the coset), all in one class with no symmetry.
    #[cfg(test)]
    pub(crate) fn truncated(depth: u8) -> Cocsep {
        let mut depths = vec![depth + 1; N_COCSEP];
        depths[cocsep(Cube::solved())] = 0;
        let mut frontier = vec![Cube::solved()];
        for d in 1..=depth {
            let mut next = Vec::new();
            for cube in frontier {
                for mv in Move::ALL {
                    let child = cube.apply_move(mv);
                    let coord = cocsep(child);
                    if depths[coord] > d {
                        depths[coord] = d;
                        next.push(child);
                    }
                }
            }
            frontier = next;
        }
        // Packed entries `class << 10 | sym_to_rep << 4 | depth` with class
        // and sym_to_rep 0: just the depth byte.
        let packed = Memory::anonymous(PACKED_LEN).unwrap();
        let bytes = unsafe { std::slice::from_raw_parts_mut(packed.ptr(), 3 * N_COCSEP + 1) };
        let mut distribution = vec![0u64; 16].into_boxed_slice();
        for (i, &d) in depths.iter().enumerate() {
            bytes[3 * i] = d;
            distribution[usize::from(d)] += 1;
        }
        Cocsep {
            entries: depths.iter().map(|&d| u32::from(d)).collect(),
            representatives: vec![Cube::solved(); N_CLASSES].into_boxed_slice(),
            self_symmetries: vec![1; N_CLASSES].into_boxed_slice(),
            distribution,
            packed,
        }
    }

    /// Base of the packed entries (see `packed`).
    #[must_use]
    pub fn packed_ptr(&self) -> *const u8 {
        self.packed.ptr()
    }

    /// Packed entry of cocsep coordinate `i` (see `packed_*`): a 4-byte
    /// unaligned load of 3 bytes and the next entry's first byte.
    #[must_use]
    #[inline(always)]
    pub fn packed(&self, i: usize) -> u32 {
        debug_assert!(i < N_COCSEP);
        unsafe { self.packed.ptr().add(3 * i).cast::<u32>().read_unaligned() }
    }

    /// Full h11 key of a cube (the reference path; the solver's hot path is
    /// `Solver::index`).
    #[must_use]
    #[inline(always)]
    pub fn full_key(&self, cube: Cube) -> u64 {
        let entry = unsafe { *self.entries.get_unchecked(cocsep(cube)) };
        let edges = cube.transform_edges(entry_sym_to_rep(entry));
        h11_key(entry_class(entry), edges)
    }

    /// hk table index of a cube.
    #[must_use]
    #[inline(always)]
    pub fn index(&self, cube: Cube, k: u32) -> u64 {
        reduce_key(self.full_key(cube), k)
    }
}

// ---------------------------------------------------------------------------
// Memory backing for huge tables
// ---------------------------------------------------------------------------

/// A memory mapping (anonymous or of a file), unmapped on drop.
pub struct Memory {
    ptr: *mut u8,
    len: usize,
    /// (wasm32) Bytes of the pages that `ptr` starts: at least `len`.
    #[cfg(all(not(unix), target_arch = "wasm32", not(wasm_threads)))]
    pages_len: usize,
}

/// wasm32 linear memory never shrinks: the pages of the largest dropped
/// `Memory` (address, bytes), for the next one that fits (e.g. a table
/// loaded again).
#[cfg(all(not(unix), target_arch = "wasm32", not(wasm_threads)))]
static SPARE_PAGES: std::sync::Mutex<(usize, usize)> = std::sync::Mutex::new((0, 0));
// (A plain block of memory: shared read-only, or written with atomics.)
unsafe impl Send for Memory {}
unsafe impl Sync for Memory {}

impl Memory {
    /// Anonymous zeroed memory, transparent huge pages requested.
    ///
    /// # Errors
    /// If `mmap` fails.
    #[cfg(unix)]
    pub fn anonymous(len: usize) -> Result<Memory, TableError> {
        // (Miri supports only these flags, and no `madvise`.)
        #[cfg(not(miri))]
        let flags = libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_NORESERVE;
        #[cfg(miri)]
        let flags = libc::MAP_PRIVATE | libc::MAP_ANONYMOUS;
        unsafe {
            let p = libc::mmap(
                std::ptr::null_mut(),
                len,
                libc::PROT_READ | libc::PROT_WRITE,
                flags,
                -1,
                0,
            );
            if p == libc::MAP_FAILED {
                return Err(TableError::Alloc {
                    bytes: len,
                    source: std::io::Error::last_os_error(),
                });
            }
            #[cfg(all(not(miri), target_os = "linux"))]
            libc::madvise(p, len, libc::MADV_HUGEPAGE);
            Ok(Memory {
                ptr: p.cast::<u8>(),
                len,
            })
        }
    }

    /// Zeroed memory where there is no `mmap` (wasm, see `try_anonymous`).
    ///
    /// # Errors
    /// If there is not enough memory.
    #[cfg(not(unix))]
    pub fn anonymous(len: usize) -> Result<Memory, TableError> {
        Memory::try_anonymous(len).ok_or_else(|| TableError::Alloc {
            bytes: len,
            source: std::io::ErrorKind::OutOfMemory.into(),
        })
    }

    /// Zeroed memory from the allocator, or `None` if there is not enough.
    #[cfg(all(not(unix), not(target_arch = "wasm32")))]
    #[must_use]
    pub fn try_anonymous(len: usize) -> Option<Memory> {
        // SAFETY: a non-zero size; freed with the same layout in `drop`.
        let ptr = unsafe { std::alloc::alloc_zeroed(Memory::layout(len)?) };
        (!ptr.is_null()).then_some(Memory { ptr, len })
    }

    /// Zeroed page-aligned memory from wasi-libc (`posix_memalign`), or
    /// `None` if there is not enough. The threads build's memory is all there
    /// from the start and never grows (see `wasm/build.rs`), and C's
    /// allocator, unlike Rust's, hands out more than `isize::MAX` (h7 is 3.6
    /// GiB).
    #[cfg(all(target_arch = "wasm32", wasm_threads))]
    #[must_use]
    pub fn try_anonymous(len: usize) -> Option<Memory> {
        let mut ptr = std::ptr::null_mut();
        // SAFETY: an out-pointer; the block is freed in `drop`.
        if unsafe { libc::posix_memalign(&raw mut ptr, 4096, len.max(1)) } != 0 {
            return None;
        }
        let ptr = ptr.cast::<u8>();
        // SAFETY: `len` bytes of the fresh block.
        unsafe { std::ptr::write_bytes(ptr, 0, len) };
        Some(Memory { ptr, len })
    }

    /// Zeroed whole pages of wasm32 linear memory (`memory.grow`), or `None`
    /// if the engine has no more (at most 4 GiB in all). Not from the
    /// allocator: it cannot hand out more than `isize::MAX` (2 GiB) at
    /// once, and h7 is 3.6 GiB.
    #[cfg(all(not(unix), target_arch = "wasm32", not(wasm_threads)))]
    #[must_use]
    pub fn try_anonymous(len: usize) -> Option<Memory> {
        const PAGE: usize = 1 << 16;
        let pages_len = len.max(1).checked_next_multiple_of(PAGE)?;
        let mut spare = SPARE_PAGES
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let (address, pages_len) = if spare.1 >= pages_len {
            let (address, spare_len) = std::mem::take(&mut *spare);
            // SAFETY: the pages of a dropped `Memory`, used by nobody else.
            unsafe {
                std::ptr::write_bytes(std::ptr::with_exposed_provenance_mut::<u8>(address), 0, len);
            }
            (address, spare_len)
        } else {
            let first_page = core::arch::wasm32::memory_grow::<0>(pages_len / PAGE);
            if first_page == usize::MAX {
                return None;
            }
            // (Fresh pages are zero.)
            (first_page * PAGE, pages_len)
        };
        Some(Memory {
            ptr: std::ptr::with_exposed_provenance_mut(address),
            len,
            pages_len,
        })
    }

    /// The allocator layout of `len` bytes (page aligned), if there is one
    /// (`len` rounded up to the alignment is at most `isize::MAX`).
    #[cfg(all(not(unix), not(target_arch = "wasm32")))]
    fn layout(len: usize) -> Option<std::alloc::Layout> {
        std::alloc::Layout::from_size_align(len.max(1), 4096).ok()
    }

    /// Shared mapping of a file (e.g. on hugetlbfs, which gives 1GB pages;
    /// not measured separately), faulted in at once.
    /// If `create`, the file is created/truncated to `len` and mapped
    /// writable, else mapped read-only.
    ///
    /// # Errors
    /// If the file cannot be opened, sized or mapped, or is shorter than
    /// `len`.
    pub fn map_file(path: &str, len: usize, create: bool) -> std::io::Result<Memory> {
        Memory::map(path, len, create, true)
    }

    /// Read-only shared mapping of a table file of at least `len` bytes;
    /// `prefault` faults it all in now (a parallel sequential read), else
    /// pages are read on first use.
    ///
    /// # Errors
    /// As `map_file`.
    pub fn map_read_only(path: &str, len: usize, prefault: bool) -> std::io::Result<Memory> {
        Memory::map(path, len, false, prefault)
    }

    #[cfg(not(unix))]
    fn map(path: &str, _: usize, _: bool, _: bool) -> std::io::Result<Memory> {
        Err(std::io::Error::new(
            std::io::ErrorKind::Unsupported,
            format!("{path}: no file mappings on this target"),
        ))
    }

    #[cfg(unix)]
    fn map(path: &str, len: usize, create: bool, prefault: bool) -> std::io::Result<Memory> {
        use std::os::unix::io::AsRawFd;
        // (Opened tables are mapped read-only: a stray write faults instead
        // of corrupting the shared table file for every process.)
        let file = std::fs::OpenOptions::new()
            .read(true)
            .write(create)
            .create(create)
            .truncate(false)
            .open(path)?;
        let hugetlbfs = file::is_hugetlbfs(path);
        if create {
            // hugetlbfs needs the size rounded up to the page size.
            let page = 1usize << 30;
            let rounded = if hugetlbfs {
                len.div_ceil(page) * page
            } else {
                len
            };
            file.set_len(rounded as u64)?;
        }
        let file_len = usize::try_from(file.metadata()?.len()).map_err(std::io::Error::other)?;
        if file_len < len {
            return Err(std::io::Error::other(format!(
                "table file {path} too small: {file_len} < {len}"
            )));
        }
        let protection = if create {
            libc::PROT_READ | libc::PROT_WRITE
        } else {
            libc::PROT_READ
        };
        // (The kernel populates with one thread: right for hugetlbfs, whose
        // pages are in memory already, and new files; other files are read
        // in parallel by `prefault`.)
        let populate_in_kernel = prefault && (create || hugetlbfs);
        #[cfg(target_os = "linux")]
        let flags = if populate_in_kernel {
            libc::MAP_SHARED | libc::MAP_POPULATE
        } else {
            libc::MAP_SHARED
        };
        #[cfg(not(target_os = "linux"))]
        let flags = libc::MAP_SHARED;
        // SAFETY: a fresh mapping of `file_len` bytes of an open file.
        let p = unsafe {
            libc::mmap(
                std::ptr::null_mut(),
                file_len,
                protection,
                flags,
                file.as_raw_fd(),
                0,
            )
        };
        if p == libc::MAP_FAILED {
            return Err(std::io::Error::last_os_error());
        }
        let memory = Memory {
            ptr: p.cast::<u8>(),
            len: file_len,
        };
        // Huge pages where the kernel and file system support them (for
        // regular files: page cache folios of 2 MiB, mapped whole).
        #[cfg(target_os = "linux")]
        // SAFETY: advice on our own mapping.
        unsafe {
            libc::madvise(p, file_len, libc::MADV_HUGEPAGE);
        }
        if prefault && !(cfg!(target_os = "linux") && populate_in_kernel) {
            memory.prefault()?;
        }
        Ok(memory)
    }

    /// Fault every page of the mapping in, reading in parallel (16 threads;
    /// a range whose thread cannot be started is read on this one).
    ///
    /// # Errors
    /// If a thread panicked.
    #[cfg(unix)]
    fn prefault(&self) -> std::io::Result<()> {
        let per = self.len.div_ceil(16).next_multiple_of(1 << 21);
        std::thread::scope(|s| {
            let mut threads = Vec::with_capacity(16);
            for start in (0..self.len).step_by(per.max(1)) {
                let len = per.min(self.len - start);
                // (A raw pointer is not `Send`: pass the address.)
                let address = self.ptr as usize + start;
                // SAFETY (both calls): a range of our own mapping.
                let fault = move || unsafe { prefault_range(address, len) };
                match std::thread::Builder::new().spawn_scoped(s, fault) {
                    Ok(thread) => threads.push(thread),
                    Err(_) => unsafe { prefault_range(address, len) },
                }
            }
            let mut result = Ok(());
            for thread in threads {
                if thread.join().is_err() {
                    result = Err(std::io::Error::other("a prefault thread panicked"));
                }
            }
            result
        })
    }

    #[must_use]
    pub fn ptr(&self) -> *mut u8 {
        self.ptr
    }
    #[must_use]
    pub fn len(&self) -> usize {
        self.len
    }
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
    /// The memory as 64-bit words, for the table generator's atomic updates.
    ///
    /// # Safety
    /// Before mutating a word, the caller must ensure the mapping is writable
    /// and that no non-atomic access or immutable byte reference overlaps the
    /// mutation. A view used only for loads may coexist with other readers.
    ///
    /// ```compile_fail,E0133
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// let memory = egg_solver::tables::Memory::anonymous(8)?;
    /// let _words = memory.words()?; // Requires an explicit unsafe contract.
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    /// If the memory is larger than a slice can be (`isize::MAX` bytes: 2
    /// GiB on 32-bit targets).
    #[expect(clippy::cast_ptr_alignment, reason = "mappings are page aligned")]
    pub unsafe fn words(&self) -> Result<&[AtomicU64], TableError> {
        self.check_slice_len()?;
        // SAFETY: our memory, of at most `isize::MAX` bytes, page aligned.
        Ok(unsafe { std::slice::from_raw_parts(self.ptr.cast::<AtomicU64>(), self.len / 8) })
    }

    /// The memory as bytes.
    ///
    /// # Errors
    /// As `words`.
    pub fn bytes(&self) -> Result<&[u8], TableError> {
        self.check_slice_len()?;
        // SAFETY: our memory, of at most `isize::MAX` bytes.
        Ok(unsafe { std::slice::from_raw_parts(self.ptr, self.len) })
    }

    /// The memory can be a slice: at most `isize::MAX` bytes.
    fn check_slice_len(&self) -> Result<(), TableError> {
        match isize::try_from(self.len) {
            Ok(_) => Ok(()),
            Err(_) => Err(TableError::TooLargeForSlice(self.len)),
        }
    }
}

/// Fault in `len` bytes from `address`: `MADV_POPULATE_READ`, else a read of
/// a byte per 4 KiB (the smallest page size).
///
/// # Safety
/// `address..address + len` is mapped (and readable).
#[cfg(unix)]
unsafe fn prefault_range(address: usize, len: usize) {
    #[cfg(target_os = "linux")]
    // SAFETY: advice on a mapped range (the caller's contract).
    unsafe {
        let range = address as *mut libc::c_void;
        if libc::madvise(range, len, libc::MADV_POPULATE_READ) == 0 {
            return;
        }
    }
    let mut sum = 0u8;
    for offset in (0..len).step_by(4096) {
        // SAFETY: within the range (the caller's contract).
        sum ^= unsafe { std::ptr::read_volatile((address + offset) as *const u8) };
    }
    std::hint::black_box(sum);
}

impl Drop for Memory {
    fn drop(&mut self) {
        #[cfg(unix)]
        // SAFETY: our own mapping, unmapped once.
        unsafe {
            libc::munmap(self.ptr.cast::<libc::c_void>(), self.len);
        }
        #[cfg(all(not(unix), not(target_arch = "wasm32")))]
        // SAFETY: allocated by `try_anonymous` with this layout (which
        // exists: it did then).
        if let Some(layout) = Memory::layout(self.len) {
            unsafe {
                std::alloc::dealloc(self.ptr, layout);
            }
        }
        #[cfg(all(target_arch = "wasm32", wasm_threads))]
        // SAFETY: from `posix_memalign` in `try_anonymous`, freed once.
        unsafe {
            libc::free(self.ptr.cast::<libc::c_void>());
        }
        #[cfg(all(not(unix), target_arch = "wasm32", not(wasm_threads)))]
        {
            let mut spare = SPARE_PAGES
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if self.pages_len > spare.1 {
                *spare = (self.ptr.expose_provenance(), self.pages_len);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// H48 table (cube48opt layout): 128-byte rows of 512 2-bit slots, one row
// per (class, msplit, eoK); the row is indexed by eslot. Each 16-byte group
// (64 slots) reserves slots 0-1 for a 4-bit minimum over the group. (Neutral
// at h11 when added; -71% nodes with h0, eslice-groups.)
// ---------------------------------------------------------------------------

pub const ROW_BYTES: u64 = 128;
pub const WORDS_PER_ROW: usize = 16;

/// Rows of table hk: one per (class, msplit, top `k` eo bits).
#[must_use]
pub fn h48_rows(k: u32) -> u64 {
    (N_CLASSES * N_MSPLIT) as u64 * (1u64 << k)
}
/// Size of the index space (including unused slots).
#[must_use]
pub fn h48_slots(k: u32) -> u64 {
    h48_rows(k) * N_SLOTS as u64
}
/// Size of table hk in bytes.
#[must_use]
pub fn h48_bytes(k: u32) -> u64 {
    h48_rows(k) * ROW_BYTES
}

/// Default base value per k (`gen <k> auto`; cube48opt's, confirmed for h4..h8
/// by nodes/cube on random:200:2026 and by solve speed). Base 9 for h4..h6
/// (23-67% fewer nodes than base 8, 7-44% fewer than base 10; h6 at 1T and 8
/// threads 15-20% faster than with base 10); h7: base 10 has 3.5% fewer
/// nodes, but with 40 lanes is 4-9% faster at 1T and 6.3% slower at 8
/// threads: a tie, so base 9 (generated in 30 s instead of 5 min on 8
/// cores); h8: base 10 (10% fewer nodes than base 9); h9, h10 as h8 and h11
/// (base 11: +10% nodes, x-h48); h0..h3 not measured.
#[must_use]
pub fn default_base(k: u32) -> u8 {
    [7, 8, 8, 8, 9, 9, 9, 9, 10, 10, 10, 10][k as usize]
}

/// u64 word index and bit shift of an entry.
#[must_use]
#[inline(always)]
pub fn entry_position(index: u64) -> (usize, u32) {
    ((index >> 5) as usize, (index & 31) as u32 * 2)
}

/// Mask of the low bits of the 2-bit slots of word `w` that are real
/// entries.
#[must_use]
#[inline(always)]
pub fn entry_low_bits(w: u64) -> u64 {
    let mut mask = 0x5555_5555_5555_5555u64;
    if w.is_multiple_of(2) {
        mask &= !0x5; // slots 0, 1: group minimum
    }
    if w % WORDS_PER_ROW as u64 == WORDS_PER_ROW as u64 - 1 {
        mask &= !(1 << 62); // slot 511 unused
    }
    mask
}

/// Which table a file holds: `k` (of hk) and the `base` of its codes.
#[derive(Clone, Copy, Debug)]
pub struct H48Meta {
    pub k: u32,
    pub base: u8,
}

/// An H48 table: 2-bit codes, 0 = "at most `base`" (then the group minimum
/// and the corner depth give a bound), 1..=3 = `base + code` (3: at least).
pub struct H48Table {
    pub memory: Memory,
    pub meta: H48Meta,
}

impl H48Table {
    #[must_use]
    #[inline(always)]
    pub fn ptr(&self) -> *const u8 {
        self.memory.ptr()
    }

    /// Returns (2-bit code, group minimum).
    #[must_use]
    #[inline(always)]
    #[expect(clippy::cast_ptr_alignment, reason = "tables are page aligned")]
    pub fn get(&self, index: u64) -> (u8, u8) {
        unsafe {
            let words = self.memory.ptr().cast_const().cast::<u64>();
            let w = (index >> 5) as usize;
            let word = *words.add(w);
            // (The group's first word holds the minimum in slots 0-1.)
            let group_min = *words.add(w & !1) & 15;
            (((word >> ((index & 31) * 2)) & 3) as u8, group_min as u8)
        }
    }

    #[inline(always)]
    pub fn prefetch(&self, index: u64) {
        // NTA: each line is read once; less L2 pollution (cocsep data).
        // (+2.6% at 48T when added, prefetch-nta.)
        // SAFETY: an entry of the table (indices are below its size).
        unsafe {
            crate::prefetch::read_once(self.memory.ptr().wrapping_add((index >> 2) as usize));
        }
    }

    /// Distribution of the 2-bit codes over real entries.
    ///
    /// # Errors
    /// If the table is larger than its memory or a slice can be, or a
    /// counting thread panicked.
    pub fn distribution(&self) -> Result<[u64; 4], TableError> {
        // SAFETY: distribution only loads the words; it never mutates them.
        let words = unsafe { self.memory.words()? };
        let len = usize::try_from(h48_bytes(self.meta.k) / 8)
            .map_err(|_| TableError::TooLarge(self.meta.k))?;
        let words = words.get(..len).ok_or(TableError::TooLarge(self.meta.k))?;
        Ok(distribution(words, crate::thread_count())?)
    }
}

/// Distribution of the 2-bit codes over the real entries of whole rows of a
/// table (`words` from the start of a row).
///
/// # Errors
/// If a thread panicked.
pub fn distribution(
    words: &[AtomicU64],
    threads: usize,
) -> Result<[u64; 4], crate::parallel::WorkerPanicked> {
    let per_thread = words.len().div_ceil(threads.max(1)).max(1);
    let mut total = [0u64; 4];
    let chunks: Vec<&[AtomicU64]> = words.chunks(per_thread).collect();
    let counts = crate::parallel::on_threads(chunks.len(), |t| {
        let mut counts = [0u64; 4];
        for (w, word) in ((t * per_thread) as u64..).zip(chunks.get(t).copied().unwrap_or(&[])) {
            let bits = word.load(Ordering::Relaxed);
            let mask = entry_low_bits(w);
            let lo = bits & mask;
            let hi = (bits >> 1) & mask;
            counts[3] += u64::from((lo & hi).count_ones());
            counts[2] += u64::from((!lo & hi).count_ones());
            counts[1] += u64::from((lo & !hi).count_ones());
            counts[0] += u64::from((mask & !lo & !hi).count_ones());
        }
        counts
    })?;
    for thread_counts in counts {
        for (sum, count) in total.iter_mut().zip(thread_counts) {
            *sum += count;
        }
    }
    Ok(total)
}

/// The source tree this binary was built from, whose `tables/` holds the
/// `.hugemeta` files of tables on hugetlbfs (which only holds page-sized
/// files). Stored in a fixed-size buffer so that the binary's layout does not
/// depend on the length of the build path: otherwise builds from different
/// worktrees place all code at different offsets, which alone moves benchmark
/// results by 1-2%.
static BUILD_DIR: [u8; 256] = {
    let path = env!("CARGO_MANIFEST_DIR").as_bytes();
    assert!(path.len() < 256, "build path too long");
    let mut buf = [0u8; 256];
    let mut i = 0;
    while i < path.len() {
        buf[i] = path[i];
        i += 1;
    }
    buf
};

/// [`BUILD_DIR`] as a string (read through `black_box`, so the padded buffer
/// is what the binary contains, not a folded copy of the path).
fn build_dir() -> String {
    let buf: &[u8; 256] = std::hint::black_box(&BUILD_DIR);
    let len = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..len]).into_owned()
}

/// The meta file of a table file (for hugetlbfs files, which cannot hold
/// small files, in the repository's `tables` directory; a hugetlbfs path
/// without a file name, like `/mnt/huge/..`, has the usual sidecar).
#[must_use]
pub fn meta_path(path: &str) -> String {
    match std::path::Path::new(path).file_name() {
        Some(name) if path.starts_with("/mnt/huge") => {
            format!("{}/tables/{}.hugemeta", build_dir(), name.to_string_lossy())
        }
        _ => format!("{path}.meta"),
    }
}

/// `k` and `base` if usable: the search relies on bounds below 16 (`base +
/// 3` and 4-bit group minima) and on the index layout of `k`.
fn checked_meta(k: u32, base: u32) -> Option<H48Meta> {
    match (k, u8::try_from(base)) {
        (0..=11, Ok(base @ 0..=12)) => Some(H48Meta { k, base }),
        _ => None,
    }
}

/// Read a table's `k` and `base`: from the file's trailer (`file`), else
/// from its sidecar meta file (`meta_path`).
///
/// # Errors
/// If neither can be read, or they do not hold `k <= 11` and a base of at
/// most 12, or the trailer's data size is not that of `k`.
pub fn read_meta(path: &str) -> Result<H48Meta, TableError> {
    if let Some(trailer) = file::read_trailer(path)? {
        return match checked_meta(trailer.k, u32::from(trailer.base)) {
            Some(meta) if trailer.data_bytes == h48_bytes(meta.k) => Ok(meta),
            _ => Err(TableError::BadTrailer {
                path: path.to_string(),
                trailer,
            }),
        };
    }
    let text = std::fs::read_to_string(meta_path(path)).map_err(|source| TableError::NoMeta {
        path: path.to_string(),
        meta_path: meta_path(path),
        source,
    })?;
    let invalid = || TableError::BadMeta(text.clone());
    let numbers: Vec<u32> = text
        .split_whitespace()
        .map(|x| x.parse().map_err(|_| invalid()))
        .collect::<Result<_, _>>()?;
    let [k, base] = numbers[..] else {
        return Err(invalid());
    };
    checked_meta(k, base).ok_or_else(invalid)
}

/// How `H48Table::open_reporting` loaded a table.
#[derive(Clone, Debug)]
pub struct LoadReport {
    /// The mode used: `Auto` resolved (to `Shm` if a segment was used).
    pub mode: file::LoadMode,
    /// The shared memory segment used, with `Shm`.
    pub segment: Option<shm::Segment>,
    /// Why no segment was used (`Auto`), or why a new one got smaller pages
    /// than it might have, and how to get them.
    pub notes: Vec<String>,
}

impl H48Table {
    /// Open a table file, loaded as `file::LoadOptions::from_env` says.
    ///
    /// # Errors
    /// See `open_with`.
    pub fn open(path: &str) -> Result<H48Table, TableError> {
        H48Table::open_with(path, &file::LoadOptions::from_env()?)
    }

    /// Open a table file. Files on hugetlbfs (1 GiB pages) and `/dev/shm`
    /// are mapped directly; other files are mapped or copied into anonymous
    /// huge-page memory, or loaded through a shared memory segment, as
    /// `options` say (see `open_reporting`).
    ///
    /// # Errors
    /// If the table's meta cannot be read (`read_meta`), the file size does
    /// not match its `k`, or reading, mapping or allocating fails.
    pub fn open_with(path: &str, options: &file::LoadOptions) -> Result<H48Table, TableError> {
        H48Table::open_reporting(path, options).map(|(table, _)| table)
    }

    /// `open_with`, and how the table was loaded. With `LoadMode::Shm` the
    /// table's shared memory segment is attached, or made from the file
    /// first (`shm`); `Auto` attaches it only if it is there and holds this
    /// file's table (else loads the file as before, with a note).
    ///
    /// # Errors
    /// As `open_with`; with `Shm`, also if the segment cannot be made or
    /// holds another table, or is being loaded by another process
    /// (`TableError::ShmLoading`: try again).
    pub fn open_reporting(
        path: &str,
        options: &file::LoadOptions,
    ) -> Result<(H48Table, LoadReport), TableError> {
        let meta = read_meta(path)?;
        let len = usize::try_from(h48_bytes(meta.k)).map_err(|_| TableError::TooLarge(meta.k))?;
        // A file of another `k` (a stale or wrong meta) would give wrong,
        // possibly too high, bounds: its size must match (plus a trailer;
        // hugetlbfs files are rounded up to whole 1 GiB pages).
        let io_error = file::io_error(path);
        let file_len = std::fs::metadata(path).map_err(io_error)?.len();
        if file_len < len as u64 || file_len >= len as u64 + file::TRAILER_BYTES + file::HUGE_PAGE {
            return Err(TableError::WrongSize {
                path: path.to_string(),
                bytes: file_len,
                k: meta.k,
                needed: len as u64,
            });
        }
        let mut report = LoadReport {
            mode: options.mode_for(path),
            segment: None,
            notes: Vec::new(),
        };
        if matches!(options.mode, file::LoadMode::Auto | file::LoadMode::Shm) {
            let create = options.mode == file::LoadMode::Shm;
            if let Some((memory, segment)) = shm::open(path, options, create, &mut report.notes)? {
                report.mode = file::LoadMode::Shm;
                report.segment = Some(segment);
                return Ok((H48Table { memory, meta }, report));
            }
        }
        let io_error = file::io_error(path);
        if report.mode == file::LoadMode::Map {
            let memory = Memory::map_read_only(path, len, options.prefault).map_err(io_error)?;
            return Ok((H48Table { memory, meta }, report));
        }
        let memory = Memory::anonymous(len)?;
        let table_file = std::fs::File::open(path).map_err(io_error)?;
        #[cfg(unix)]
        read_parallel(&table_file, &memory, len).map_err(file::io_error(path))?;
        #[cfg(not(unix))]
        {
            // SAFETY: `len` bytes of our own memory.
            let buf = unsafe { std::slice::from_raw_parts_mut(memory.ptr(), len) };
            std::io::Read::read_exact(&mut &table_file, buf).map_err(file::io_error(path))?;
        }
        Ok((H48Table { memory, meta }, report))
    }

    /// A table from the bytes of a table file already in `memory` (the data,
    /// then its trailer in the last 4 KiB; e.g. a file fetched into
    /// WebAssembly memory), checked as `open` checks a file: the trailer's
    /// `k`, base and data size against the size, and with `verify` the
    /// data's checksum, if the trailer records one (`threads` threads).
    ///
    /// # Errors
    /// If there is no valid trailer, the size does not match it, or the
    /// checksum differs.
    pub fn from_file_memory(
        memory: Memory,
        verify: bool,
        threads: usize,
    ) -> Result<H48Table, TableError> {
        let file_len = memory.len() as u64;
        let trailer_start = file_len
            .checked_sub(file::TRAILER_BYTES)
            .ok_or(TableError::NotATableFile(file_len))?;
        // (Slices of at most 1 GiB: wasm32 has no slices over 2 GiB, h7 is
        // 3.6 GiB.)
        let piece = |start: u64, len: u64| -> &[u8] {
            // (Offsets within the memory, whose length is a `usize`, are
            // `usize`s too; out of range, the piece is empty.)
            match (usize::try_from(start), usize::try_from(len)) {
                (Ok(start), Ok(len))
                    if start
                        .checked_add(len)
                        .is_some_and(|end| end <= memory.len()) =>
                {
                    // SAFETY: within the memory (checked), which is ours and
                    // not written meanwhile.
                    unsafe { std::slice::from_raw_parts(memory.ptr().add(start), len) }
                }
                _ => &[],
            }
        };
        let trailer = file::Trailer::parse(piece(trailer_start, file::TRAILER_BYTES))?
            .ok_or(TableError::NoTrailer)?;
        let meta = checked_meta(trailer.k, u32::from(trailer.base))
            .filter(|meta| trailer.data_bytes == h48_bytes(meta.k))
            .ok_or(TableError::UnusableTrailer(trailer))?;
        // (As in `open_with`; hugetlbfs files have up to a page of slack.)
        let data_len = trailer.data_bytes;
        if trailer_start < data_len || trailer_start >= data_len + file::HUGE_PAGE {
            return Err(TableError::WrongMemorySize {
                bytes: file_len,
                k: meta.k,
                needed: data_len,
            });
        }
        if let (true, Some(want)) = (verify, trailer.checksum) {
            // (Pieces of whole checksum chunks: the same chunk hashes as one
            // slice of all the data.)
            let piece_len = (file::CHECKSUM_CHUNK << 10) as u64;
            let mut hashes = Vec::new();
            for i in 0..data_len.div_ceil(piece_len) {
                let start = i * piece_len;
                hashes.extend(file::chunk_hashes(
                    piece(start, piece_len.min(data_len - start)),
                    threads,
                )?);
            }
            let got = file::combine_hashes(data_len, &hashes);
            if got != want {
                return Err(TableError::Checksum { got, want });
            }
        }
        Ok(H48Table { memory, meta })
    }

    /// An all-zero table (every bound is then the corner depth), for unit
    /// tests with `Cocsep::truncated`.
    #[cfg(test)]
    pub(crate) fn zeroed(k: u32, base: u8) -> H48Table {
        H48Table {
            memory: Memory::anonymous(usize::try_from(h48_bytes(k)).unwrap()).unwrap(),
            meta: H48Meta { k, base },
        }
    }

    /// The trailer describing this table (distribution and checksum
    /// computed from the data, with `threads` threads).
    ///
    /// # Errors
    /// If the table is larger than its memory or a slice can be, or a
    /// thread panicked.
    pub fn trailer(&self, threads: usize) -> Result<file::Trailer, TableError> {
        let data = self.data()?;
        Ok(file::Trailer {
            k: self.meta.k,
            base: self.meta.base,
            data_bytes: data.len() as u64,
            distribution: Some(self.distribution()?),
            checksum: Some(file::checksum(data, threads)?),
        })
    }

    /// The table's data: the first `h48_bytes(k)` bytes of its memory.
    ///
    /// # Errors
    /// If the table is larger than its memory or a slice can be.
    pub fn data(&self) -> Result<&[u8], TableError> {
        let too_large = TableError::TooLarge(self.meta.k);
        let len = usize::try_from(h48_bytes(self.meta.k)).map_err(|_| too_large)?;
        self.memory
            .bytes()?
            .get(..len)
            .ok_or(TableError::TooLarge(self.meta.k))
    }

    /// Write the table to a new file at `path`: the data, then its trailer.
    ///
    /// # Errors
    /// If the file cannot be written.
    pub fn save(&self, path: &str) -> Result<(), TableError> {
        let trailer = self.trailer(crate::thread_count())?.to_bytes();
        let data = self.data()?;
        let write = || -> std::io::Result<()> {
            let mut out = std::fs::File::create(path)?;
            std::io::Write::write_all(&mut out, data)?;
            std::io::Write::write_all(&mut out, &trailer)?;
            out.sync_all()
        };
        write().map_err(file::io_error(path))
    }
}

/// Read the first `len` bytes of `table_file` into `memory`, in parallel (16
/// threads: a disk or page cache copy of up to tens of GiB; a range whose
/// thread cannot be started is read on this one), each 64 MiB piece dropped
/// from the page cache once copied (the copy is what is used).
///
/// # Errors
/// If a read fails, or a thread panicked.
#[cfg(unix)]
fn read_parallel(table_file: &std::fs::File, memory: &Memory, len: usize) -> std::io::Result<()> {
    let threads = 16usize;
    // (Whole 2 MiB pages per thread.)
    let per_thread = len.div_ceil(threads).next_multiple_of(1 << 21);
    let len = len.min(memory.len());
    std::thread::scope(|s| {
        let mut spawned = Vec::with_capacity(threads);
        let mut result = Ok(());
        for t in 0..threads {
            let start = t * per_thread;
            let end = ((t + 1) * per_thread).min(len);
            if start >= end {
                continue;
            }
            // SAFETY (both calls): `start..end` is within the memory, and
            // each range is read once, by one thread.
            let read = move || unsafe { read_range(table_file, memory, start, end) };
            match std::thread::Builder::new().spawn_scoped(s, read) {
                Ok(thread) => spawned.push(thread),
                Err(_) => {
                    result = result.and(unsafe { read_range(table_file, memory, start, end) });
                }
            }
        }
        for thread in spawned {
            let read = thread
                .join()
                .unwrap_or_else(|_| Err(std::io::Error::other("a reading thread panicked")));
            result = result.and(read);
        }
        result
    })
}

/// Read bytes `start..end` of `table_file` into the same bytes of `memory`.
///
/// # Safety
/// `start..end` is within `memory`, and nothing else accesses those bytes
/// meanwhile.
#[cfg(unix)]
unsafe fn read_range(
    table_file: &std::fs::File,
    memory: &Memory,
    start: usize,
    end: usize,
) -> std::io::Result<()> {
    use std::os::unix::fs::FileExt;
    // SAFETY: as the caller promises.
    let buf = unsafe { std::slice::from_raw_parts_mut(memory.ptr().add(start), end - start) };
    for (i, piece) in buf.chunks_mut(64 << 20).enumerate() {
        let offset = (start + (i << 26)) as u64;
        table_file.read_exact_at(piece, offset)?;
        // (Advice only: skipped if the numbers do not fit.)
        #[cfg(target_os = "linux")]
        if let (Ok(offset), Ok(len)) = (
            libc::off_t::try_from(offset),
            libc::off_t::try_from(piece.len()),
        ) {
            use std::os::unix::io::AsRawFd;
            // SAFETY: advice on an open file.
            unsafe {
                libc::posix_fadvise(
                    table_file.as_raw_fd(),
                    offset,
                    len,
                    libc::POSIX_FADV_DONTNEED,
                );
            }
        }
    }
    Ok(())
}

/// A fresh path for a test's scratch file: in the temporary folder, named by
/// the process (WASI has neither a temporary folder nor process ids: there it
/// is under `$TMPDIR` or `/tmp`, which the runner preopens, named by the time).
#[cfg(test)]
pub(crate) fn scratch_path(name: &str) -> std::path::PathBuf {
    #[cfg(not(target_os = "wasi"))]
    let (dir, id) = (std::env::temp_dir(), u128::from(std::process::id()));
    #[cfg(target_os = "wasi")]
    let (dir, id) = (
        std::path::PathBuf::from(std::env::var("TMPDIR").unwrap_or_else(|_| "/tmp".into())),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_nanos()),
    );
    dir.join(format!("egg-solver-{name}-{id}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::cubie::*;

    /// Atomic generator writes finish before any immutable byte view is made.
    #[test]
    fn atomic_updates_finish_before_byte_reads() {
        let memory = Memory::anonymous(16).unwrap();
        let values = [0x0123_4567_89ab_cdef_u64, 0xfedc_ba98_7654_3210];
        {
            // SAFETY: fresh writable memory, exposed only as atomic words
            // until both scoped workers have finished.
            let words = unsafe { memory.words().unwrap() };
            std::thread::scope(|scope| {
                for (word, value) in words.iter().zip(values) {
                    scope.spawn(move || word.store(value, Ordering::Relaxed));
                }
            });
        }
        let bytes = memory.bytes().unwrap();
        assert_eq!(&bytes[..8], &values[0].to_ne_bytes());
        assert_eq!(&bytes[8..], &values[1].to_ne_bytes());
    }

    /// Tables open only with a valid meta and a file of the size its `k`
    /// needs (a wrong meta would give wrong, possibly too high, bounds).
    #[test]
    #[cfg_attr(miri, ignore = "files")]
    fn table_meta_and_size_are_checked() {
        let dir = scratch_path("meta");
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("h0").to_string_lossy().into_owned();
        let len = h48_bytes(0);
        std::fs::write(&path, vec![0u8; usize::try_from(len).unwrap()]).unwrap();
        let open_with = |meta: &str| {
            std::fs::write(meta_path(&path), meta).unwrap();
            H48Table::open(&path).map(|t| (t.meta.k, t.meta.base))
        };
        assert_eq!(open_with("0 8\n").unwrap(), (0, 8));
        for bad in ["0 13", "12 8", "0", "0 8 1", "x 8", "0 -1", ""] {
            assert!(open_with(bad).is_err(), "meta {bad:?}");
        }
        // The file of an h0 table is too small for h1.
        assert!(open_with("1 8").is_err());
        std::fs::remove_dir_all(&dir).unwrap();
    }

    /// A table file's bytes in memory (as JavaScript hands a fetched file to
    /// wasm) give the table its trailer describes; damaged data is found
    /// with `verify`, a wrong size or a missing trailer always.
    #[test]
    #[cfg_attr(miri, ignore = "a 29 MiB checksum is too slow under Miri")]
    fn table_from_file_memory_is_checked() {
        let data_len = usize::try_from(h48_bytes(0)).unwrap();
        let file_of = |data: &dyn Fn(usize) -> u8, trailer: &file::Trailer, extra: usize| {
            let memory = Memory::anonymous(data_len + extra + 4096).unwrap();
            // SAFETY: our own fresh memory, not yet shared.
            let bytes = unsafe { std::slice::from_raw_parts_mut(memory.ptr(), memory.len()) };
            for (i, b) in bytes[..data_len].iter_mut().enumerate() {
                *b = data(i);
            }
            let end = bytes.len();
            bytes[end - 4096..].copy_from_slice(&trailer.to_bytes());
            memory
        };
        let pattern = |i: usize| u8::try_from(i % 251).unwrap();
        let reference: Vec<u8> = (0..data_len).map(pattern).collect();
        let trailer = file::Trailer {
            k: 0,
            base: 8,
            data_bytes: data_len as u64,
            distribution: None,
            checksum: Some(file::checksum(&reference, 3).unwrap()),
        };
        let table = H48Table::from_file_memory(file_of(&pattern, &trailer, 0), true, 2).unwrap();
        assert_eq!((table.meta.k, table.meta.base), (0, 8));
        assert_eq!(&table.memory.bytes().unwrap()[..data_len], &reference[..]);
        // (Room before the trailer is allowed, as on hugetlbfs.)
        assert!(H48Table::from_file_memory(file_of(&pattern, &trailer, 8192), true, 1).is_ok());
        let damaged = |i: usize| if i == 12_345 { 7 } else { pattern(i) };
        assert!(H48Table::from_file_memory(file_of(&damaged, &trailer, 0), true, 1).is_err());
        assert!(H48Table::from_file_memory(file_of(&damaged, &trailer, 0), false, 1).is_ok());
        let wrong_k = file::Trailer { k: 1, ..trailer };
        assert!(H48Table::from_file_memory(file_of(&pattern, &wrong_k, 0), false, 1).is_err());
        let no_trailer = Memory::anonymous(data_len + 4096).unwrap();
        assert!(H48Table::from_file_memory(no_trailer, false, 1).is_err());
        assert!(H48Table::from_file_memory(Memory::anonymous(100).unwrap(), false, 1).is_err());
    }

    /// A table file opened for solving (hugetlbfs or /dev/shm) is mapped
    /// read-only.
    #[test]
    #[cfg_attr(miri, ignore = "files")]
    #[cfg_attr(not(target_os = "linux"), ignore = "Linux mappings")]
    fn opened_table_file_is_read_only() {
        let path = format!("/dev/shm/egg-solver-test-{}-h0", std::process::id());
        let len = usize::try_from(h48_bytes(0)).unwrap();
        std::fs::write(&path, vec![0u8; len]).unwrap();
        std::fs::write(meta_path(&path), "0 8\n").unwrap();
        let table = H48Table::open(&path).unwrap();
        let start = table.ptr() as usize;
        let maps = std::fs::read_to_string("/proc/self/maps").unwrap();
        let perms = maps
            .lines()
            .find(|l| l.starts_with(&format!("{start:x}-")))
            .map(|l| l.split_whitespace().nth(1).unwrap().to_string());
        assert_eq!(perms.as_deref(), Some("r--s"), "{maps}");
        drop(table);
        std::fs::remove_file(meta_path(&path)).unwrap();
        std::fs::remove_file(&path).unwrap();
    }

    #[test]
    #[cfg_attr(miri, ignore = "Cocsep::generate is too slow under Miri")]
    fn cocsep_classes_and_distribution() {
        let cs = Cocsep::generate().unwrap();
        assert_eq!(cs.representatives.len(), 3393);
        assert_eq!(
            &cs.distribution[..10],
            &[1, 6, 63, 468, 3068, 15438, 53814, 71352, 8784, 96]
        );
        // The cocsep class and depth are invariant under symmetry.
        let mut rng = Rng(7);
        for _ in 0..200 {
            let c = Cube::from_cubie(&CubieCube::random(&mut rng));
            let d0 = cs.entries[cocsep(c)];
            for t in 0..48 {
                let d1 = cs.entries[cocsep(c.transform(t))];
                assert_eq!(entry_class(d0), entry_class(d1));
                assert_eq!(entry_depth(d0), entry_depth(d1));
            }
            let p = cs.packed(cocsep(c));
            assert_eq!(packed_class(p), entry_class(d0));
            assert_eq!(packed_sym_to_rep(p), entry_sym_to_rep(d0));
            assert_eq!(packed_depth(p), entry_depth(d0));
            // sym_to_rep maps the cube's corners onto the representative.
            let r = cs.representatives[entry_class(d0)];
            assert_eq!(cocsep(c.transform(entry_sym_to_rep(d0))), cocsep(r));
        }
    }
}
